namespace StremioWT
{
    // Traductions : le texte français sert de clé, L.T("Rejoindre") renvoie le texte dans la langue choisie.
    // Chaque ligne de la table : français, puis une colonne par langue dans l'ordre de Languages.
    static class L
    {
        public static readonly (string Code, string Name)[] Languages =
        {
            ("fr", "Français"), ("en", "English"), ("es", "Español"), ("pt", "Português"), ("zh", "中文"),
            ("hi", "हिन्दी"), ("ar", "العربية"), ("bn", "বাংলা"), ("ru", "Русский"), ("id", "Bahasa Indonesia"),
        };

        public static string Lang { get; private set; } = "en";
        // Arabe : lecture de droite à gauche (sinon les mots latins, « StremioWT », « IP »…, se placent mal dans la phrase).
        public static bool IsRightToLeft => Lang == "ar";
        static Dictionary<string, string> current = new Dictionary<string, string>();
        static Dictionary<string, string> english = new Dictionary<string, string>();

        public static void Init()
        {
            var saved = Program.Config.TryGetValue("lang", out var l) ? l as string : null;
            Lang = Supported(saved) ? saved : "en";
            current = Column(Lang);
            english = Column("en");
        }

        public static void Save(string code)
        {
            if (!Supported(code)) return;
            Program.Config["lang"] = code;
            Program.SaveConfig(Program.Config);
        }

        static bool Supported(string code) => code != null && Languages.Any(x => x.Code == code);

        static Dictionary<string, string> Column(string code)
        {
            int i = Array.FindIndex(Languages, x => x.Code == code);
            return Table.Where(row => i < row.Length && !string.IsNullOrEmpty(row[i])).ToDictionary(row => row[0], row => row[i]);
        }

        public static string T(string fr) => current.TryGetValue(fr, out var t) ? t : english.TryGetValue(fr, out var en) ? en : fr;
        public static string F(string fr, params object[] args) => string.Format(T(fr), args);

        public static Dictionary<string, string> ForPage() => Table.ToDictionary(row => row[0], row => T(row[0]));

        static string[] E(params string[] t) => t;

